CREATE TABLE IF NOT EXISTS dentec.calendar_revisions (_key text PRIMARY KEY,_parent text,_position integer NOT NULL DEFAULT 0,_order bigint NOT NULL DEFAULT nextval('dentec.entity_order'),_fields text[] NOT NULL,_undefined text[] NOT NULL DEFAULT '{}',"version" integer,"at" text,"catalogueRevision" integer);
CREATE TABLE IF NOT EXISTS dentec.calendar_states (_key text PRIMARY KEY,_parent text,_position integer NOT NULL DEFAULT 0,_order bigint NOT NULL DEFAULT nextval('dentec.entity_order'),_fields text[] NOT NULL,_undefined text[] NOT NULL DEFAULT '{}',"schemaVersion" integer,"year" integer,"campus" text,"offer" text,"regime" text,"weekdays" integer[],"weekConfirmed" boolean,"weekEvidence" text,"assessmentStages" integer,"secondSemesterIntake" boolean,"teacherDayDate" text,"ignoredHistory" text[]);
