CREATE TABLE IF NOT EXISTS dentec.institutional_events (_key text PRIMARY KEY,_parent text,_position integer NOT NULL DEFAULT 0,_order bigint NOT NULL DEFAULT nextval('dentec.entity_order'),_fields text[] NOT NULL,_undefined text[] NOT NULL DEFAULT '{}',"id" text,"name" text,"start" text,"end" text,"kind" text,"category" text,"evidence" text,"offers" text[],"modalities" text[],"requirementId" text,"hours" double precision,"assessmentAutoStart" text,"institutional" boolean,"active" boolean);
