DO $private_access$
DECLARE api_role text;
BEGIN
 FOR api_role IN SELECT rolname FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role') LOOP
  EXECUTE format('REVOKE ALL ON SCHEMA dentec FROM %I',api_role);
  EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA dentec FROM %I',api_role);
  EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA dentec FROM %I',api_role);
 END LOOP;
END
$private_access$;
DO $backend_role$
BEGIN
 IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'dentec_test_app') THEN
GRANT USAGE ON SCHEMA dentec TO "dentec_test_app";
GRANT USAGE, SELECT ON SEQUENCE dentec.entity_order TO "dentec_test_app";
GRANT SELECT, INSERT, UPDATE, DELETE ON dentec.root_fields TO "dentec_test_app";
DROP POLICY IF EXISTS "backend_bde3a48e5f48" ON dentec.root_fields;
CREATE POLICY "backend_bde3a48e5f48" ON dentec.root_fields FOR ALL TO "dentec_test_app" USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON dentec.record_properties TO "dentec_test_app";
DROP POLICY IF EXISTS "backend_bde3a48e5f48" ON dentec.record_properties;
CREATE POLICY "backend_bde3a48e5f48" ON dentec.record_properties FOR ALL TO "dentec_test_app" USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON dentec.users TO "dentec_test_app";
DROP POLICY IF EXISTS "backend_bde3a48e5f48" ON dentec.users;
